const require_terminal_internal = require('./terminal-internal.cjs');
const require_text_layout = require('./text-layout.cjs');
const require_usage = require('./usage.cjs');

//#region src/terminal-width.ts
const automaticWidth = Symbol.for("@optique/core/automaticWidth");
/**
* Marks runner options without changing their public type. The enumerable
* symbol survives the option copies made by Program and context runners.
* @param options The options whose width was automatically detected.
* @param onResolved Receives the effective width before message rendering.
* @returns A marked copy of the options.
* @internal
*/
function withAutomaticWidth(options, onResolved = () => {}) {
	return {
		...options,
		[automaticWidth]: onResolved
	};
}
/**
* Checks whether a width is a runner hint rather than an explicit constraint.
* @param options The formatting or runner options.
* @returns Whether automatic width fallback is enabled.
* @internal
*/
function hasAutomaticWidth(options) {
	return automaticWidth in options && typeof options[automaticWidth] === "function";
}
/**
* Reports the resolved width before any opaque message formatter runs.
* @param options The marked formatting options.
* @param width The width selected by layout validation.
* @internal
*/
function reportAutomaticWidth(options, width) {
	if (automaticWidth in options && typeof options[automaticWidth] === "function") options[automaticWidth](width);
}
/**
* Measures the minimum usage layout, allowing long atomic terms to overflow.
* @param programName The program name shown in the usage line.
* @param usage The visible usage tree.
* @param label The rendered usage label, including its trailing space.
* @param theme The semantic terminal theme.
* @returns The minimum feasible width for the usage block.
* @internal
*/
function minimumUsageWidth(programName, usage, label, theme) {
	const labelWidth = require_text_layout.measureText(label).lastLineWidth;
	const programWidth = Math.max(0, ...[...require_terminal_internal.fragmentTokens(require_terminal_internal.formatTerminalTerm({
		type: "programName",
		programName
	}, theme))].map((token) => token.width));
	const atomicWidth = usage.reduce((widest, term) => Math.max(widest, require_text_layout.measureText(require_usage.formatUsageTerm(term, {
		theme,
		maxWidth: 1
	})).maxLineWidth), 0);
	return Math.max(require_text_layout.measureText(label).maxLineWidth, labelWidth + Math.max(programWidth, Math.min(atomicWidth, programWidth + labelWidth)));
}

//#endregion
exports.hasAutomaticWidth = hasAutomaticWidth;
exports.minimumUsageWidth = minimumUsageWidth;
exports.reportAutomaticWidth = reportAutomaticWidth;
exports.withAutomaticWidth = withAutomaticWidth;